     * 1. Calls the `getImplementationAddress` function from the `Core` contract, passing the proxy address as an argument.
     * 2. Returns the implementation address associated with the proxy.
     */
    function getImplementationAddress(address proxy) internal view returns (address) {
        return Core.getImplementationAddress(proxy);
    }

